<script setup lang="ts">import{computed}from 'vue';import type{Exact}from '../types/domain';import{fmt}from '../utils/format';const p=defineProps<{exact:Exact}>();const max=computed(()=>Math.max(...p.exact.distribution.map(d=>d.probability),1e-300));const x=(s:number)=>42+(s-p.exact.support_lower+.5)/(p.exact.support_size)*820;const bw=computed(()=>820/p.exact.support_size);</script><template><div class="distribution-scroll"><svg viewBox="0 0 930 330" role="img" aria-label="固定边际的全部离散条件概率与均值距离双侧尾"><line x1="42" y1="260" x2="862" y2="260" class="axis"/><rect v-for="d in exact.distribution" :key="d.s" :x="x(d.s)-bw/2+.2" :y="260-d.probability/max*200" :width="Math.max(.25,bw-.4)" :height="d.probability/max*200" :class="d.in_tail?'tail-mass':'central-mass'"><title>S={{d.s}},P={{d.probability}},入尾={{d.in_tail}}</title></rect><line :x1="x(exact.observed_sum)" :x2="x(exact.observed_sum)" y1="28" y2="260" class="observed-line"/><line :x1="x(exact.distribution_mean)" :x2="x(exact.distribution_mean)" y1="42" y2="260" class="mean-line"/><text :x="Math.min(780,Math.max(42,x(exact.observed_sum)+6))" y="22">观察 S={{exact.observed_sum}}</text><text :x="Math.min(740,Math.max(42,x(exact.distribution_mean)+6))" y="42">E[S]={{fmt(exact.distribution_mean,3)}}</text><text x="42" y="286">{{exact.support_lower}}</text><text x="820" y="286">{{exact.support_upper}}</text><text x="360" y="314">所有层 A 成功数之和 S / 固定边际</text></svg></div><p class="plot-caption"><i class="tail-key"/>砖红点纳入双侧尾；每根柱为一个支持点。均值距离按有理数判定，不是Fisher概率排序双侧。</p></template>
